15	/// Backoff applied *before* each retry; the number of attempts is one more than
16	/// the number of delays (initial call + one retry per delay).
17	const RPC_RETRY_DELAYS: [Duration; 3] = [
18	    Duration::from_secs(5),
19	    Duration::from_secs(15),
20	    Duration::from_secs(45),
21	];
22	
23	const RPC_MAX_ATTEMPTS: usize = RPC_RETRY_DELAYS.len() + 1;
24	
25	pub(crate) const RECEIPT_TIMEOUT: Duration = Duration::from_secs(120);
26	
27	/// Percentage a replacement transaction must reach relative to the one it replaces.
28	///
29	/// Geth's default `--txpool.pricebump` is 10%, applied to `maxFeePerGas` and
30	/// `maxPriorityFeePerGas` independently - bumping only one is rejected. 112 leaves
31	/// headroom for integer truncation and for nodes configured above the default.
32	const FEE_BUMP_PERCENT: u128 = 112;
33	
34	/// Ceiling on a replacement fee, as a multiple of the current market estimate.
35	/// Resending every dispatcher cycle compounds, so escalation has to stop somewhere.
36	const FEE_CEILING_MULTIPLE: u128 = 4;
37	
38	/// Fee for a replacement transaction: at least `FEE_BUMP_PERCENT` of what the stuck
39	/// transaction paid (or the node rejects it as underpriced), and at least the current
40	/// market rate (or it clears the mempool's rule but still will not be mined).
41	///
42	/// Returns `None` once the result would exceed the ceiling, meaning: stop bumping and
43	/// keep waiting. The last replacement stays in the mempool and remains mineable, so
44	/// the deposit is never at risk of being spent twice however long it takes.
45	pub(crate) fn bumped_fee(previous: u128, market_estimate: u128) -> Option<u128> {
46	    let bumped = (previous.saturating_mul(FEE_BUMP_PERCENT) / 100).max(market_estimate);
47	    let ceiling = market_estimate.saturating_mul(FEE_CEILING_MULTIPLE);
48	    (bumped <= ceiling).then_some(bumped)
49	}
