171	    const GWEI: u128 = 1_000_000_000;
172	
173	    #[test]
174	    fn bump_clears_geth_ten_percent_threshold() {
175	        // Market roughly level with what the stuck tx paid - the realistic stall.
176	        let out = bumped_fee(30 * GWEI, 30 * GWEI).unwrap();
177	        assert!(out >= 30 * GWEI * 110 / 100, "{out} does not clear a 10% pricebump over 30 gwei");
178	    }
179	
180	    #[test]
181	    fn no_bump_when_already_far_above_market() {
182	        // Paying 30 gwei into a 1 gwei market: the tx will mine on its own merits, and
183	        // bumping past the ceiling would only overpay. Holding is the right answer.
184	        assert_eq!(bumped_fee(30 * GWEI, GWEI), None);
185	    }
186	
187	    #[test]
188	    fn bump_floors_at_market_when_market_has_risen() {
189	        // 112% of 10 gwei is still far under a 50 gwei market: it would be accepted as a
190	        // replacement yet never mined, so the market rate has to win.
191	        assert_eq!(bumped_fee(10 * GWEI, 50 * GWEI), Some(50 * GWEI));
192	    }
193	
194	    #[test]
195	    fn bump_stops_at_ceiling() {
196	        // Already at 4x market; another 12% would exceed it.
197	        assert_eq!(bumped_fee(40 * GWEI, 10 * GWEI), None);
198	    }
199	
200	    #[test]
201	    fn bump_allowed_below_ceiling() {
202	        assert!(bumped_fee(20 * GWEI, 10 * GWEI).is_some(), "2x market is inside the 4x ceiling");
203	    }
204	
205	    #[test]
206	    fn does_not_overflow_on_extreme_inputs() {
207	        // Degenerate values cannot occur in practice; the requirement is simply that
208	        // the arithmetic saturates instead of panicking in debug builds.
209	        let _ = bumped_fee(u128::MAX / 2, u128::MAX);
210	        let _ = bumped_fee(u128::MAX, GWEI);
211	        let _ = bumped_fee(0, 0);
212	    }
213	}
