118	pub async fn load_route_settings(
119	    route: &Route,
120	    arb_outbox_address: Address,
121	    arb_outbox_provider: &DynProvider<Ethereum>,
122	) -> RouteSettings {
123	    info!(logger = "Startup", route = route.name, "Loading route settings from contracts");
124	
125	    let avg_block_time_ms = get_avg_block_time_ms(arb_outbox_provider).await;
126	    info!(logger = "Startup", route = route.name, avg_block_time_ms, "Block time computed");
127	
128	    let arb_outbox = IOutbox::new(arb_outbox_address, arb_outbox_provider.clone());
129	    let rollup_address = crate::retry_rpc_or_panic("get rollup address from Arbitrum outbox", || async { arb_outbox.rollup().call().await }).await;
130	    let rollup = IRollup::new(rollup_address, arb_outbox_provider.clone());
131	    let confirm_period_blocks: u64 = crate::retry_rpc_or_panic("get confirmPeriodBlocks", || async { rollup.confirmPeriodBlocks().call().await }).await
132	        .max(14458);
133	    info!(logger = "Startup", route = route.name, confirm_period_blocks, "Rollup config loaded");
134	
135	    let outbox = IVeaOutbox::new(route.outbox_address, route.outbox_provider.clone());
136	    let sequencer_delay_limit = crate::retry_rpc_or_panic("get sequencerDelayLimit", || async { outbox.sequencerDelayLimit().call().await }).await.to::<u64>();
137	    let min_challenge_period = crate::retry_rpc_or_panic("get minChallengePeriod", || async { outbox.minChallengePeriod().call().await }).await.to::<u64>();
138	    let epoch_period = crate::retry_rpc_or_panic("get epochPeriod", || async { outbox.epochPeriod().call().await }).await.to::<u64>();
139	    info!(logger = "Startup", route = route.name, sequencer_delay_limit, epoch_period, min_challenge_period, "Outbox params loaded");
140	
141	    let relay_delay_secs = (confirm_period_blocks * avg_block_time_ms / 1000) + TIMING_SAFETY_BUFFER_SECS;
142	    let start_verification_delay = sequencer_delay_limit + epoch_period + TIMING_SAFETY_BUFFER_SECS;
143	    let min_challenge_period_with_buffer = min_challenge_period + TIMING_SAFETY_BUFFER_SECS;
144	    let sync_lookback_secs = relay_delay_secs + start_verification_delay + min_challenge_period_with_buffer + TIMING_SAFETY_BUFFER_SECS;
145	
146	    info!(logger = "Startup", route = route.name, relay_delay_secs, start_verification_delay, min_challenge_period = min_challenge_period_with_buffer, sync_lookback_secs, "Route timing computed");
147	
148	    RouteSettings {
149	        relay_delay_secs,
150	        start_verification_delay,
151	        min_challenge_period: min_challenge_period_with_buffer,
152	        sync_lookback_secs,
153	    }
154	}
