        at: Mutex<Vec<Instant>>,
    }

    impl Attempts {
        /// Logs one attempt and returns its 0-based index.
        fn record(&self) -> usize {
            let mut at = self.at.lock().expect("attempt log");
            at.push(Instant::now());
            at.len() - 1
        }

        fn count(&self) -> usize {
            self.at.lock().expect("attempt log").len()
        }

        /// The delay observed before each retry, i.e. the applied backoff schedule.
